import sys
import math

def trailing_brute(n):
    s = str(math.factorial(n))
    cnt = 0
    for ch in reversed(s):
        if ch == '0':
            cnt += 1
        else:
            break
    return cnt

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    print(trailing_brute(n))

import sys

def trailing_opt(n):
    cnt = 0
    for i in range(5, n + 1, 5):
        x = i
        while x % 5 == 0:
            cnt += 1
            x //= 5
    return cnt

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    print(trailing_opt(n))

import sys

def trailing_best(n):
    cnt = 0
    while n:
        n //= 5
        cnt += n
    return cnt

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    print(trailing_best(n))
